package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.Bundle;import android.provider.Settings;import java.util.*;
/** Shared secure preferences are read by the separately installed Leo IME. */
public final class InputSettingsActivity extends LeoActivity {
    static final String MODE="leo_keypad_default_mode",DELAY="leo_keypad_multitap_ms";
    static final String[] MODES=L.array(new String[]{"Ultimul mod folosit","abc","ABC","123","T9 română","T9 ROMÂNĂ"});
    protected void onResume(){super.onResume();show();}
    private void show(){int mode=Settings.Secure.getInt(getContentResolver(),MODE,-1),delay=Settings.Secure.getInt(getContentResolver(),DELAY,850);list(L.t("Tastatură și text"),Arrays.asList(L.t("La început · ")+MODES[Math.max(0,Math.min(5,mode+1))],L.t("Pauză multi-tap · ")+delay+" ms",L.t("Text Leo · ")+(getSharedPreferences("appearance",0).getBoolean("large-text",false)?L.t("Mai mare"):"Normal"),L.t("Dicționar personal"),L.t("Ajutor taste"),L.t("Memorează alegerile T9 · ")+(Settings.Secure.getInt(getContentResolver(),"leo_keypad_learn_choices",0)==1?L.t("Da"):L.t("Nu"))),0,new Choice(){public void pick(int i){if(i==0)options(L.t("Mod la începutul editării"),MODES,new Choice(){public void pick(int at){setMode(at-1);show();}});else if(i==1)options(L.t("Pauză între litere"),new String[]{L.t("Rapid · 500 ms"),"Normal · 850 ms",L.t("Lent · 1200 ms")},new Choice(){public void pick(int at){setDelay(new int[]{500,850,1200}[at]);show();}});else if(i==2)options(L.t("Dimensiunea textului Leo"),new String[]{"Normal",L.t("Mai mare")},new Choice(){public void pick(int at){getSharedPreferences("appearance",0).edit().putBoolean("large-text",at==1).apply();show();}});else if(i==3){try{startActivity(new Intent().setComponent(new ComponentName("ro.leo.keypad","ro.leo.keypad.DictionaryActivity")));}catch(RuntimeException e){notice(L.t("Instalează versiunea nouă a tastaturii"));}}else if(i==5){try{Settings.Secure.putInt(getContentResolver(),"leo_keypad_learn_choices",Settings.Secure.getInt(getContentResolver(),"leo_keypad_learn_choices",0)==1?0:1);show();}catch(RuntimeException e){notice(L.t("Preferință indisponibilă"));}}else help();}},"",null);}
    void setMode(int value){try{if(value<-1||value>4)throw new IllegalArgumentException();Settings.Secure.putInt(getContentResolver(),MODE,value);}catch(RuntimeException e){notice(L.t("Preferința tastaturii nu poate fi salvată"));}}
    void setDelay(int value){try{if(value<400||value>1500)throw new IllegalArgumentException();Settings.Secure.putInt(getContentResolver(),DELAY,value);}catch(RuntimeException e){notice(L.t("Pauza nu poate fi salvată"));}}
    private void help(){begin(L.t("Taste pentru text"));android.widget.ScrollView scroll=new android.widget.ScrollView(this);scroll.addView(text(L.t("# · abc / ABC / 123 / T9\n2–9 · litere sau predicție\n0 · spațiu\n1 / * · semne și sugestii\nSoft dreapta · ștergere\n\nPreferințele noi se aplică la următorul editor. Câmpurile de parolă rămân fără predicție; câmpurile numerice folosesc cifre."),17));root.addView(scroll,new android.widget.LinearLayout.LayoutParams(-1,0,1));scroll.setFocusable(true);scroll.requestFocus();back=new Runnable(){public void run(){show();}};footer("",L.t("Derulează"),L.t("Înapoi"));}
}
